The use of `any` type bypasses TypeScript's type safety. Consider defining a proper interface for the doc structure or using type guards to validate the structure before filtering and mapping.
```suggestion
interface SourceDocInfo {
  path: string;
}

interface SourceDocData {
  // `default` holds the page body/component; other properties are spread through.
  default: unknown;
  // Allow additional properties without losing type safety on `default`.
  [key: string]: unknown;
}

interface SourceDoc {
  info?: SourceDocInfo;
  data: SourceDocData;
}

function isValidDoc(doc: unknown): doc is SourceDoc {
  if (typeof doc !== 'object' || doc === null) return false;
  const maybeDoc = doc as { info?: { path?: unknown }; data?: unknown };
  if (!maybeDoc.info || typeof maybeDoc.info.path !== 'string') return false;
  if (typeof maybeDoc.data !== 'object' || maybeDoc.data === null) return false;
  return true;
}

// Map the docs from .source to the format expected by loader
// Note: docs from .source is wrapped by _runtime.doc(), not a plain array
const mappedDocs = docs
  .filter(isValidDoc)
  .map((doc) => {
    let path = doc.info!.path.replace(/\.mdx?$/, '');
    // Convert index.mdx to empty path for root /docs route
    if (path === 'index') path = '';
```
